        }
        rows = build_chain_summary_rows(["d", "d"], snapshots)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[-1], ["chain-summary", 1, 1, 0, 0])

    def test_cell_rows_sorted_by_record_then_field(self) -> None:
        snapshots = {
